var TYPE=require("../../tokenizer").TYPE,HASH=TYPE.Hash;module.exports={name:"Hash",structure:{value:String},parse:function(){var t=this.scanner.tokenStart;return this.eat(HASH),{type:"Hash",loc:this.getLocation(t,this.scanner.tokenStart),value:this.scanner.substrToCursor(t+1)}},generate:function(t){this.chunk("#"),this.chunk(t.value)}};